using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using TransPort.Web.Models;using TransPort.Web.Services;
namespace TransPort.Web.Areas.Gestion.Controllers;
[Area("Gestion"),Authorize(Roles="AdministradorGeneral,Gerente,Empleado,Operativo"),Route("gestion/maquinarias")]
public sealed class MaquinariasController(ITransportApiClient api,ILogger<MaquinariasController> log):Controller
{
 [HttpGet("")]public async Task<IActionResult>Index(string?estado,int?sedeId,string?busqueda,CancellationToken ct){try{return View(new MaquinariaPaginaViewModel{Estado=estado,SedeId=sedeId,Busqueda=busqueda,Equipos=await api.MaquinariasAsync(estado,sedeId,busqueda,ct),Opciones=await api.MaquinariaOpcionesAsync(ct)});}catch(Exception e)when(e is HttpRequestException or TransportApiException){log.LogError(e,"No cargó maquinaria");TempData["Error"]="No fue posible consultar maquinaria.";return View(new MaquinariaPaginaViewModel());}}[HttpPost("crear")]public async Task<IActionResult>Crear(MaquinariaCrearViewModel m,CancellationToken ct){try{var id=await api.CrearMaquinariaAsync(m,ct);return RedirectToAction(nameof(Detalle),new{id});}catch(TransportApiException){TempData["Error"]="No fue posible crear el equipo.";return RedirectToAction(nameof(Index));}}[HttpGet("{id:int}")]public async Task<IActionResult>Detalle(int id,CancellationToken ct){var x=await api.MaquinariaAsync(id,ct);if(x is null)return NotFound();ViewBag.Opciones=await api.MaquinariaOpcionesAsync(ct);return View(x);}[HttpPost("{id:int}/contratos")]public async Task<IActionResult>Contrato(int id,MaquinariaContratoCrearViewModel m,CancellationToken ct){m.EquipoId=id;try{await api.CrearContratoMaquinariaAsync(m,ct);TempData["Exito"]="Contrato reservado.";}catch(TransportApiException){TempData["Error"]="No fue posible reservar el equipo.";}return RedirectToAction(nameof(Detalle),new{id});}[HttpPost("{id:int}/contratos/{contratoId:long}")]public async Task<IActionResult>EstadoContrato(int id,long contratoId,string estado,decimal?horasDevolucion,string?observacion,CancellationToken ct){try{await api.EstadoContratoMaquinariaAsync(contratoId,estado,horasDevolucion,observacion,ct);}catch(TransportApiException){TempData["Error"]="Transición de contrato inválida.";}return RedirectToAction(nameof(Detalle),new{id});}[HttpPost("{id:int}/mantenimientos")]public async Task<IActionResult>Mantenimiento(int id,MaquinariaMantenimientoCrearViewModel m,CancellationToken ct){m.EquipoId=id;try{await api.CrearMantenimientoMaquinariaAsync(m,ct);}catch(TransportApiException){TempData["Error"]="No fue posible programar mantenimiento.";}return RedirectToAction(nameof(Detalle),new{id});}[HttpPost("{id:int}/mantenimientos/{mantenimientoId:long}")]public async Task<IActionResult>EstadoMantenimiento(int id,long mantenimientoId,string estado,string?observacion,CancellationToken ct){try{await api.EstadoMantenimientoMaquinariaAsync(mantenimientoId,estado,observacion,ct);}catch(TransportApiException){TempData["Error"]="Transición de mantenimiento inválida.";}return RedirectToAction(nameof(Detalle),new{id});}[HttpPost("{id:int}/eliminar"),Authorize(Roles="AdministradorGeneral")]public async Task<IActionResult>Eliminar(int id,CancellationToken ct){await api.EliminarMaquinariaAsync(id,ct);return RedirectToAction(nameof(Index));}
}
